(()=>{'use strict';const $=id=>document.getElementById(id);let mode='single';function configure(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='mode')||!['single','wrap'].includes(input.mode))throw new Error('Mode must be single or wrap');mode=input.mode;$('demo').dataset.layout=mode==='single'?'observed':'proposed';$('singleMode').setAttribute('aria-pressed',String(mode==='single'));$('wrapMode').setAttribute('aria-pressed',String(mode==='wrap'));$('layoutStatus').textContent=mode==='single'?'One horizontal line: some choices extend beyond the visible width.':'The same five choices wrap onto multiple lines and stay visible.';return{mode,choices:['Filters','In-store','Get it fast','Price','All deals']}}$('singleMode').onclick=()=>configure({mode:'single'});$('wrapMode').onclick=()=>configure({mode:'wrap'});configure({mode:'single'});if(window.location&&typeof URLSearchParams!=='undefined'){const q=new URLSearchParams(window.location.search);if(q.has('mode'))try{configure({mode:q.get('mode')})}catch{}}if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_filter_layout_demo',title:'Compare filter layouts',description:'Switch between single-line and wrapped presentation of the same demo filter choices. No shopping action occurs.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['single','wrap']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:configure},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}window.layoutDemo={configure,getState:()=>({mode})};})();